  ('out_of_scope_rules', '[{"code":"panel_work","severity":"block","t":{"uz":"Elektr shchiti ichidagi ishlar","ru":"Работы внутри электрощита","en":"Work inside the distribution board"}},{"code":"grounding","severity":"block","t":{"uz":"Yerga ulash tizimini yaratish yoki o''zgartirish","ru":"Создание или изменение системы заземления","en":"Creating or changing the earthing system"}},{"code":"three_phase","severity":"block","t":{"uz":"3 fazali tarmoq","ru":"Трёхфазная сеть","en":"Three-phase supply"}},{"code":"wet_zone","severity":"block","t":{"uz":"Ho''l zona (vannaxona, dush, hojatxona)","ru":"Влажная зона (ванная, душ, санузел)","en":"Wet zone (bathroom, shower, toilet)"}},{"code":"aluminium","severity":"block","t":{"uz":"Eski alyuminiy simlar","ru":"Старая алюминиевая проводка","en":"Old aluminium wiring"}},{"code":"damaged_wiring","severity":"block","t":{"uz":"Shikastlangan sim belgilari (kuyish, hid, uchqun)","ru":"Признаки повреждённой проводки (гарь, запах, искры)","en":"Signs of damaged wiring (burns, smell, sparks)"}},{"code":"high_power","severity":"block","t":{"uz":"3,5 kW dan kuchli bitta qurilma liniyasi","ru":"Линия для прибора мощнее 3,5 кВт","en":"Line for a single appliance above 3.5 kW"}},{"code":"boiler","severity":"block","t":{"uz":"Suv isitgich (boyler) liniyasi","ru":"Линия водонагревателя (бойлера)","en":"Water heater (boiler) line"}},{"code":"room_too_large","severity":"warn","t":{"uz":"Xona katta (30 m² dan ortiq) — bu ilova bitta kichik xona uchun","ru":"Комната большая (более 30 м²) — приложение рассчитано на одну небольшую комнату","en":"Room is large (over 30 m²) — this app is for one small room"}},{"code":"too_many_sockets","severity":"warn","t":{"uz":"Bitta guruhda rozetkalar ko''p — ikkinchi guruh kerak bo''lishi mumkin","ru":"Много розеток в одной группе — может понадобиться вторая группа","en":"Many sockets in one circuit — a second circuit may be needed"}},{"code":"dedicated_line","severity":"warn","t":{"uz":"Kuchli qurilma uchun alohida liniya va avtomat kerak (shchitga ulash — elektrik)","ru":"Для мощного прибора нужна отдельная линия и автомат (подключение в щите — электрик)","en":"A powerful appliance needs a dedicated line and breaker (panel connection by an electrician)"}},{"code":"wood_hidden","severity":"warn","t":{"uz":"Yog''och devorda yashirin simlar — elektrik bilan maslahatlashing","ru":"Скрытая проводка в деревянной стене — проконсультируйтесь с электриком","en":"Concealed wiring in a wooden wall — consult an electrician"}},{"code":"no_pe","severity":"warn","t":{"uz":"Uyda PE (yerga ulash) simi yo''q — RCD va yerga ulash haqida elektrik bilan maslahatlashing","ru":"В доме нет провода PE — проконсультируйтесь с электриком об УЗО и заземлении","en":"No PE (earth) conductor — consult an electrician about RCD and earthing"}},{"code":"vdrop_high","severity":"warn","t":{"uz":"Kuchlanish yo''qotilishi yuqori — kabel kesimini oshiring","ru":"Высокие потери напряжения — увеличьте сечение кабеля","en":"High voltage drop — increase the cable cross-section"}}]'::jsonb),
